"""Holding a slot for a TTL, then confirming it."""

from __future__ import annotations


class SlotTaken(Exception):
    """Raised when a slot is already held or booked."""


class HoldExpired(Exception):
    """Raised when a confirm arrives after the hold's deadline."""


class Reservations:
    """Reserve a slot for ``ttl`` seconds, then confirm or lose it.

    A hold is recorded with the time it was taken and expires exactly at
    ``reserved_at + ttl`` (inclusive). A confirmed booking is permanent.
    """

    def __init__(self, ttl: float) -> None:
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        self.ttl = ttl
        self._holds: dict[str, float] = {}      # slot -> reserved_at
        self._confirmed: set[str] = set()

    def _live_hold(self, slot: str, now: float) -> bool:
        """Is there a hold on ``slot`` that is still live at ``now``?"""
        reserved_at = self._holds.get(slot)
        if reserved_at is None:
            return False
        if now > reserved_at + self.ttl:
            # The deadline has passed; the hold is dead.
            del self._holds[slot]
            return False
        return True

    def reserve(self, slot: str, now: float) -> float:
        """Hold ``slot`` at ``now``; return the expiry time."""
        if slot in self._confirmed or self._live_hold(slot, now):
            raise SlotTaken(slot)
        self._holds[slot] = now
        return now + self.ttl

    def confirm(self, slot: str, now: float) -> None:
        """Finalize a held slot. Raises HoldExpired after the deadline."""
        if slot in self._confirmed:
            return
        if not self._live_hold(slot, now):
            raise HoldExpired(f"{slot}: no live hold")
        del self._holds[slot]
        self._confirmed.add(slot)

    def is_free(self, slot: str, now: float) -> bool:
        """Is ``slot`` available to reserve at ``now``?"""
        if slot in self._confirmed:
            return False
        return not self._live_hold(slot, now)

"""A cache bounded by time-to-live and by least-recently-used capacity."""

from __future__ import annotations


class LruTtlCache:
    """Hold at most ``cap`` entries, each living at most ``ttl`` seconds.

    Entries expire ``ttl`` seconds after they were last set, and when the
    cache is full the live entry whose last use is oldest is evicted.
    """

    def __init__(self, cap: int, ttl: float) -> None:
        if cap < 1:
            raise ValueError("cap must be at least 1")
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        self.cap = cap
        self.ttl = ttl
        # key -> (value, set_at, last_used)
        self._store: dict[str, tuple[object, float, float]] = {}

    def _is_expired(self, entry: tuple[object, float, float], now: float) -> bool:
        return now - entry[1] >= self.ttl

    def get(self, key: str, now: float) -> object | None:
        """Return the value for ``key``, or None if absent or expired."""
        entry = self._store.get(key)
        if entry is None:
            return None
        if self._is_expired(entry, now):
            del self._store[key]
            return None
        value = entry[0]
        self._store[key] = (value, entry[1], now)  # refresh recency
        return value

    def set(self, key: str, value: object, now: float) -> None:
        """Store ``value`` under ``key`` set at ``now``."""
        # An expired entry never occupies capacity: drop them all first.
        expired = [k for k, e in self._store.items() if self._is_expired(e, now)]
        for k in expired:
            del self._store[k]

        if key not in self._store and len(self._store) >= self.cap:
            lru = min(self._store, key=lambda k: self._store[k][2])
            del self._store[lru]

        self._store[key] = (value, now, now)

    def __len__(self) -> int:
        return len(self._store)

"""Holding a slot for a TTL, then confirming it."""

from __future__ import annotations


class SlotTaken(Exception):
    """Raised when a slot is already held or booked."""


class HoldExpired(Exception):
    """Raised when a confirm arrives after the hold's deadline."""


class Reservations:
    """Reserve a slot for ``ttl`` seconds, then confirm or lose it.

    A hold is live while ``now <= reserved_at + ttl`` (the deadline is
    inclusive). Once ``now`` passes that instant the hold is dead: it can no
    longer be confirmed and the slot is free to reserve again. A confirmed
    booking is permanent.
    """

    def __init__(self, ttl: float) -> None:
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        self.ttl = ttl
        self._holds: dict[str, float] = {}      # slot -> reserved_at
        self._confirmed: set[str] = set()

    def _hold_is_live(self, slot: str, now: float) -> bool:
        """Is the recorded hold on ``slot`` still live at ``now``?"""
        return now <= self._holds[slot] + self.ttl

    def reserve(self, slot: str, now: float) -> float:
        """Hold ``slot`` at ``now``; return the expiry time."""
        if slot in self._confirmed:
            raise SlotTaken(slot)
        if slot in self._holds:
            if self._hold_is_live(slot, now):
                raise SlotTaken(slot)
            # The previous hold has expired; drop it and take the slot.
            del self._holds[slot]
        self._holds[slot] = now
        return now + self.ttl

    def confirm(self, slot: str, now: float) -> None:
        """Finalize a held slot. Raises HoldExpired after the deadline."""
        if slot in self._confirmed:
            return
        if slot not in self._holds:
            raise HoldExpired(f"{slot}: no live hold")
        if not self._hold_is_live(slot, now):
            del self._holds[slot]
            raise HoldExpired(f"{slot}: hold expired")
        del self._holds[slot]
        self._confirmed.add(slot)

    def is_free(self, slot: str, now: float) -> bool:
        """Is ``slot`` available to reserve at ``now``?"""
        if slot in self._confirmed:
            return False
        if slot in self._holds:
            return not self._hold_is_live(slot, now)
        return True

"""Applying sequenced account-update messages exactly once."""

from __future__ import annotations


class Consumer:
    """Apply (account, seq, delta) messages to per-account balances.

    Messages carry a monotonically increasing sequence number per account,
    starting at 1. A message is applied only when its sequence is exactly the
    next one expected for that account; redeliveries are no-ops and stale
    messages older than the newest applied sequence are dropped. Messages that
    arrive ahead of a gap are held until the gap is filled, then flushed in
    order.
    """

    def __init__(self) -> None:
        self.balances: dict[str, int] = {}
        # Next sequence number expected per account (1-based).
        self._next_seq: dict[str, int] = {}
        # Held out-of-order messages per account: seq -> delta.
        self._held: dict[str, dict[int, int]] = {}

    def apply(self, account: str, seq: int, delta: int) -> bool:
        """Apply ``delta`` to ``account``'s balance. Returns True if applied."""
        expected = self._next_seq.get(account, 1)

        if seq < expected:
            # Stale redelivery: already applied, drop it.
            return False

        if seq > expected:
            # Gap: hold the message, do not apply yet.
            self._held.setdefault(account, {})[seq] = delta
            return False

        # seq == expected: apply it and flush any now-contiguous held messages.
        self.balances[account] = self.balances.get(account, 0) + delta
        expected += 1

        held = self._held.get(account)
        if held:
            while expected in held:
                self.balances[account] += held.pop(expected)
                expected += 1
            if not held:
                del self._held[account]

        self._next_seq[account] = expected
        return True

    def balance(self, account: str) -> int:
        return self.balances.get(account, 0)

"""A cache bounded by time-to-live and by least-recently-used capacity."""

from __future__ import annotations


class LruTtlCache:
    """Hold at most ``cap`` entries, each living at most ``ttl`` seconds.

    Entries are stored with the time they were set and evicted in
    least-recently-used order.  A ``get`` refreshes recency and returns ``None``
    for an expired entry, dropping it.  A ``set`` first drops expired entries so
    they never occupy capacity, then evicts the live entry whose last use is
    oldest when the cache is full.
    """

    def __init__(self, cap: int, ttl: float) -> None:
        if cap < 1:
            raise ValueError("cap must be at least 1")
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        self.cap = cap
        self.ttl = ttl
        # key -> (value, set_at); iteration order is least- to most-recently used
        self._store: dict[str, tuple[object, float]] = {}

    def _expired(self, entry: tuple[object, float], now: float) -> bool:
        return now - entry[1] >= self.ttl

    def get(self, key: str, now: float) -> object | None:
        """Return the value for ``key``, or None if absent or expired."""
        entry = self._store.get(key)
        if entry is None:
            return None
        if self._expired(entry, now):
            del self._store[key]
            return None
        self._store.move_to_end(key)
        return entry[0]

    def set(self, key: str, value: object, now: float) -> None:
        """Store ``value`` under ``key`` set at ``now``."""
        # An expired entry never occupies capacity: drop all of them first.
        for k in [k for k, e in self._store.items() if self._expired(e, now)]:
            del self._store[k]
        if key not in self._store and len(self._store) >= self.cap:
            lru = next(iter(self._store))  # least-recently-used
            del self._store[lru]
        self._store[key] = (value, now)
        self._store.move_to_end(key)

    def __len__(self) -> int:
        return len(self._store)

