    A hold is recorded with the time it was taken and expires exactly at
    ``reserved_at + ttl`` (inclusive): confirming at that instant still
    succeeds, while confirming any later raises :class:`HoldExpired` and
    frees the slot for a new reservation.  A confirmed booking is permanent.
    """

    def __init__(self, ttl: float) -> None:
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        self.ttl = ttl
