            raise SlotTaken(slot)
        self._holds[slot] = now
        return now + self.ttl

    def confirm(self, slot: str, now: float) -> None:
        """Finalize a held slot. Raises HoldExpired after the deadline."""
        if slot in self._confirmed:
            return
        if not self._hold_is_live(slot, now):
            self._holds.pop(slot, None)
            raise HoldExpired(f"{slot}: no live hold")
        del self._holds[slot]
        self._confirmed.add(slot)

    def is_free(self, slot: str, now: float) -> bool:
        """Is ``slot`` available to reserve at ``now``?"""
        return slot not in self._confirmed and not self._hold_is_live(slot, now)

"""Applying sequenced account-update messages exactly once."""

from __future__ import annotations


class Consumer:
    """Apply (account, seq, delta) messages to per-account balances.

    Messages carry a monotonically increasing sequence number per account.
    A message is applied only when its sequence is exactly the next expected
    one. Redeliveries and stale (older) messages are dropped as no-ops, while
    messages that arrive early (a gap) are held until the gap is filled.
    """

    def __init__(self) -> None:
        self.balances: dict[str, int] = {}
        # Newest applied sequence number per account (0 == nothing applied).
        self._applied: dict[str, int] = {}
        # Held messages per account keyed by their sequence number.
        self._held: dict[str, dict[int, int]] = {}

    def apply(self, account: str, seq: int, delta: int) -> bool:
        """Apply ``delta`` to ``account``'s balance. Returns True if applied."""
        newest = self._applied.get(account, 0)

        # Redelivery or stale message: already applied, drop it.
        if seq <= newest:
            return False

        # Future message: hold it until the gap is filled.
        if seq > newest + 1:
            self._held.setdefault(account, {})[seq] = delta
            return False

        # seq == newest + 1: apply it, then flush any held successors.
        self._apply_delta(account, delta)
        self._applied[account] = seq
        self._flush(account)
        return True

    def _flush(self, account: str) -> None:
        held = self._held.get(account)
        if not held:
            return
        while True:
            nxt = self._applied[account] + 1
            if nxt not in held:
                break
            self._apply_delta(account, held.pop(nxt))
            self._applied[account] = nxt

    def _apply_delta(self, account: str, delta: int) -> None:
        self.balances[account] = self.balances.get(account, 0) + delta

    def balance(self, account: str) -> int:
        return self.balances.get(account, 0)

