    Messages carry a monotonically increasing sequence number per account,
    starting at 1. A message is applied only when its sequence is exactly the
    next expected one; redeliveries and stale out-of-order messages are
    dropped, and messages that arrive ahead of a gap are held until the gap
    is filled.
    """

    def __init__(self) -> None:
        self.balances: dict[str, int] = {}
        # Next sequence number expected for each account.
        self._next_seq: dict[str, int] = {}
        # Held messages keyed by account then sequence number.
        self._held: dict[str, dict[int, int]] = {}

    def apply(self, account: str, seq: int, delta: int) -> bool:
        """Apply ``delta`` to ``account``'s balance. Returns True if applied."""
        expected = self._next_seq.get(account, 1)

        if seq < expected:
            # Already applied or otherwise stale: never rewind the balance.
            return False

        if seq > expected:
            # A gap exists; hold this message until the gap is filled.
            self._held.setdefault(account, {})[seq] = delta
            return False

        # seq == expected: apply it and flush any now-consecutive held messages.
        self._apply(account, delta)
        self._next_seq[account] = expected + 1

        held = self._held.get(account)
        if held:
            nxt = self._next_seq[account]
            while nxt in held:
                self._apply(account, held.pop(nxt))
                nxt += 1
            self._next_seq[account] = nxt
            if not held:
                del self._held[account]

        return True

    def _apply(self, account: str, delta: int) -> None:
        self.balances[account] = self.balances.get(account, 0) + delta

    def balance(self, account: str) -> int:
        return self.balances.get(account, 0)

