    Sequence numbers are monotonically increasing per account. A message is
    applied only when its sequence is exactly the next one expected for that
    account. Redeliveries and stale (older) messages are dropped, and messages
    that arrive ahead of a gap are held until the gap is filled.
    """

    def __init__(self) -> None:
        self.balances: dict[str, int] = {}
        # Next sequence number expected per account (1-based).
        self._next_seq: dict[str, int] = {}
        # Held messages per account: seq -> delta, awaiting their turn.
        self._held: dict[str, dict[int, int]] = {}

    def apply(self, account: str, seq: int, delta: int) -> bool:
        """Apply ``delta`` to ``account``'s balance. Returns True if applied."""
        next_seq = self._next_seq.get(account, 1)

        if seq < next_seq:
            # Stale redelivery: already applied (or superseded). Drop it.
            return False

        if seq > next_seq:
            # Gap: hold the message until the missing sequences arrive.
            self._held.setdefault(account, {})[seq] = delta
            return False

        # seq == next_seq: apply, then flush any consecutively held messages.
        self.balances[account] = self.balances.get(account, 0) + delta
        next_seq += 1

        held = self._held.get(account)
        while held and next_seq in held:
            self.balances[account] += held.pop(next_seq)
            next_seq += 1

        self._next_seq[account] = next_seq
        return True

    def balance(self, account: str) -> int:
        return self.balances.get(account, 0)

