    Each account has a monotonically increasing sequence number. A message is
    applied only when its sequence is exactly the next one after the newest
    applied sequence for that account. Redeliveries and stale (older) messages
    are no-ops, and messages that arrive before a gap is filled are held until
    the gap closes, then flushed in order.
    """

    def __init__(self) -> None:
        self.balances: dict[str, int] = {}
        # Newest applied sequence per account (0 means nothing applied yet).
        self._applied_seq: dict[str, int] = {}
        # Held messages per account, keyed by sequence number.
        self._held: dict[str, dict[int, int]] = {}

    def apply(self, account: str, seq: int, delta: int) -> bool:
        """Apply ``delta`` to ``account``'s balance. Returns True if applied."""
        applied = self._applied_seq.get(account, 0)

        # Redelivery of the newest message or a stale (older) message: drop it.
        if seq <= applied:
            return False

        # A gap: hold the message until the missing sequences arrive.
        if seq > applied + 1:
            self._held.setdefault(account, {})[seq] = delta
            return False

        # In-order message: apply it, then flush any held successors.
        self._apply_one(account, seq, delta)
        self._flush(account)
        return True

    def _apply_one(self, account: str, seq: int, delta: int) -> None:
        self.balances[account] = self.balances.get(account, 0) + delta
        self._applied_seq[account] = seq

    def _flush(self, account: str) -> None:
        held = self._held.get(account)
        if not held:
            return
        while True:
            next_seq = self._applied_seq.get(account, 0) + 1
            if next_seq not in held:
