class Consumer:
    """Apply (account, seq, delta) messages to per-account balances.

    Messages carry a monotonically increasing sequence number per account.
    A message is applied only when its sequence is exactly the next expected
    one; redeliveries and stale older messages are dropped, and messages that
    arrive ahead of a gap are held until the gap is filled.
    """

    def __init__(self) -> None:
        self.balances: dict[str, int] = {}
        # Highest sequence number applied so far, per account.
        self._last_applied: dict[str, int] = {}
        # Held messages waiting for a gap to be filled: account -> {seq: delta}.
        self._held: dict[str, dict[int, int]] = {}

    def apply(self, account: str, seq: int, delta: int) -> bool:
        """Apply ``delta`` to ``account``'s balance. Returns True if applied."""
        last = self._last_applied.get(account, 0)

        # Redelivery of an already-applied message, or a stale older message.
        if seq <= last:
            return False

        if seq > last + 1:
            # A gap: hold the message, do not apply it yet.
            self._held.setdefault(account, {})[seq] = delta
            return False

        # seq == last + 1: apply it, then flush any held consecutive messages.
        self._apply_one(account, seq, delta)
        held = self._held.get(account)
        if held:
            nxt = seq + 1
            while nxt in held:
                self._apply_one(account, nxt, held.pop(nxt))
                nxt += 1
        return True

    def _apply_one(self, account: str, seq: int, delta: int) -> None:
        self.balances[account] = self.balances.get(account, 0) + delta
        self._last_applied[account] = seq

    def balance(self, account: str) -> int:
        return self.balances.get(account, 0)

