class Consumer:
    """Apply (account, seq, delta) messages to per-account balances.

    Messages carry a monotonically increasing sequence number per account.
    A message is applied only when its sequence is exactly the next expected
    one. Redeliveries and out-of-order older messages are dropped, and gaps
    are held until the missing messages arrive.
    """

    def __init__(self) -> None:
        self.balances: dict[str, int] = {}
        # Next sequence number expected for each account (1-based).
        self._next_seq: dict[str, int] = {}
        # Held messages keyed by account then sequence.
        self._held: dict[str, dict[int, int]] = {}

    def apply(self, account: str, seq: int, delta: int) -> bool:
        """Apply ``delta`` to ``account``'s balance. Returns True if applied."""
        expected = self._next_seq.get(account, 1)

        if seq < expected:
            # Stale redelivery: already applied or superseded. Drop it.
            return False

        if seq > expected:
            # Gap: hold the message until the missing sequences arrive.
            self._held.setdefault(account, {})[seq] = delta
            return False

        # seq == expected: apply it and flush any now-contiguous held messages.
        self._apply_delta(account, delta)
        self._next_seq[account] = expected + 1
        self._flush(account)
        return True

    def _flush(self, account: str) -> None:
        held = self._held.get(account)
        if not held:
            return
        next_seq = self._next_seq[account]
        while next_seq in held:
            self._apply_delta(account, held.pop(next_seq))
            next_seq += 1
            self._next_seq[account] = next_seq
        if not held:
            del self._held[account]

    def _apply_delta(self, account: str, delta: int) -> None:
        self.balances[account] = self.balances.get(account, 0) + delta

    def balance(self, account: str) -> int:
        return self.balances.get(account, 0)

