        expected = self._next_seq.get(account, 1)

        if seq < expected:
            # Redelivery or stale out-of-order message: drop it.
            return False

        if seq > expected:
            # Gap: hold the message, do not apply it yet.
            self._pending.setdefault(account, {})[seq] = delta
            return False

