        self._apply(account, delta)
        self._next_seq[account] = expected + 1

        pending = self._pending.get(account)
        if pending:
            while True:
                nxt = self._next_seq[account]
                if nxt not in pending:
                    break
                self._apply(account, pending.pop(nxt))
                self._next_seq[account] = nxt + 1
            if not pending:
                del self._pending[account]

        return True

