    applied only when its sequence equals that next number; messages that
    arrive early (creating a gap) are held until the gap is filled, and
    messages whose sequence has already been applied are dropped as no-ops.
    """

    def __init__(self) -> None:
        self.balances: dict[str, int] = {}
        # Next expected sequence number per account (messages start at 1).
        self._next_seq: dict[str, int] = {}
        # Held out-of-order messages per account: seq -> delta.
        self._pending: dict[str, dict[int, int]] = {}

    def apply(self, account: str, seq: int, delta: int) -> bool:
        """Apply ``delta`` to ``account``'s balance. Returns True if applied.

        A message is applied only when its ``seq`` is exactly the next one
        expected for ``account``. Older (already-applied) sequences are
        dropped, and newer sequences are held until the gap is filled.
        """
        next_seq = self._next_seq.get(account, 1)

        if seq < next_seq:
            # Stale redelivery: already applied, so this is a no-op.
            return False

        if seq > next_seq:
            # Gap: hold the message, do not apply it yet.
            self._pending.setdefault(account, {})[seq] = delta
            return False

        # seq == next_seq: apply it and flush any now-contiguous held messages.
        self.balances[account] = self.balances.get(account, 0) + delta
        next_seq += 1

        pending = self._pending.get(account)
        if pending is not None:
            while next_seq in pending:
                self.balances[account] += pending.pop(next_seq)
                next_seq += 1
            if not pending:
                del self._pending[account]

        self._next_seq[account] = next_seq
        return True

    def balance(self, account: str) -> int:
        return self.balances.get(account, 0)

