class Consumer:
    """Apply (account, seq, delta) messages to per-account balances.

    Messages carry a monotonically increasing sequence number per account.
    A message is applied only when its sequence is exactly the next expected
    one. Redeliveries and older messages are dropped; messages that arrive
    early (a gap) are held until the gap is filled, then flushed in order.
    """

    def __init__(self) -> None:
        self.balances: dict[str, int] = {}
        # Newest applied sequence per account; 0 means nothing applied yet.
        self._last_seq: dict[str, int] = {}
        # Held messages per account: seq -> delta, for sequences beyond the
        # next expected one.
        self._pending: dict[str, dict[int, int]] = {}

    def apply(self, account: str, seq: int, delta: int) -> bool:
        """Apply ``delta`` to ``account``'s balance. Returns True if applied."""
        last = self._last_seq.get(account, 0)

        # Duplicate or stale delivery: already applied or superseded.
        if seq <= last:
            return False

        pending = self._pending.setdefault(account, {})

        # Not the next expected sequence: hold it, do not apply yet.
        if seq != last + 1:
            pending[seq] = delta
            return False

        # Apply this message and flush any now-contiguous held messages.
        self._apply_delta(account, delta)
        self._last_seq[account] = seq

        nxt = seq + 1
        while nxt in pending:
            self._apply_delta(account, pending.pop(nxt))
            self._last_seq[account] = nxt
            nxt += 1

        return True

    def _apply_delta(self, account: str, delta: int) -> None:
        self.balances[account] = self.balances.get(account, 0) + delta

    def balance(self, account: str) -> int:
        return self.balances.get(account, 0)

