    Messages carry a monotonically increasing sequence number per account,
    starting at 1. A message is applied only when its sequence is exactly the
    next expected one. Redeliveries and stale (older) messages are no-ops, and
    messages that arrive ahead of a gap are held until the gap is filled.
    """

    def __init__(self) -> None:
        self.balances: dict[str, int] = {}
        # Next sequence number expected for each account.
        self._next_seq: dict[str, int] = {}
        # Held messages keyed by (account, seq) -> delta.
        self._held: dict[tuple[str, int], int] = {}

    def apply(self, account: str, seq: int, delta: int) -> bool:
        """Apply ``delta`` to ``account``'s balance. Returns True if applied."""
        expected = self._next_seq.get(account, 1)

        if seq < expected:
            # Stale redelivery — already applied, drop it.
            return False

        if seq > expected:
            # A gap: hold the message until the missing sequences arrive.
            self._held[(account, seq)] = delta
            return False

        # seq == expected: apply and flush any consecutively held messages.
        self.balances[account] = self.balances.get(account, 0) + delta
        expected += 1
        while (account, expected) in self._held:
            self.balances[account] += self._held.pop((account, expected))
            expected += 1
        self._next_seq[account] = expected
        return True

    def balance(self, account: str) -> int:
        return self.balances.get(account, 0)

