        self.balances: dict[str, int] = {}
        # Newest applied sequence per account (0 means nothing applied yet).
        self._last_applied: dict[str, int] = {}
        # Held out-of-order messages: account -> {seq: delta}.
        self._pending: dict[str, dict[int, int]] = {}

    def apply(self, account: str, seq: int, delta: int) -> bool:
        """Apply ``delta`` to ``account``'s balance. Returns True if applied."""
        last = self._last_applied.get(account, 0)

        if seq <= last:
            # Duplicate redelivery or stale message: no-op.
            return False

        if seq == last + 1:
            self._apply_now(account, seq, delta)
            self._flush(account)
            return True

        # Future message: hold it until the gap is filled.
        self._pending.setdefault(account, {})[seq] = delta
        return False

    def _apply_now(self, account: str, seq: int, delta: int) -> None:
        self.balances[account] = self.balances.get(account, 0) + delta
        self._last_applied[account] = seq

    def _flush(self, account: str) -> None:
        pending = self._pending.get(account)
        if not pending:
            return
        nxt = self._last_applied[account] + 1
        while nxt in pending:
            delta = pending.pop(nxt)
            self._apply_now(account, nxt, delta)
            nxt += 1

    def balance(self, account: str) -> int:
        return self.balances.get(account, 0)

