        """Drop timestamps that have fallen out of ``key``'s window."""
        cutoff = now - self.window_s
        stamps = self._history.get(key)
        if not stamps:
            return []
        stamps = [t for t in stamps if t > cutoff]
        if stamps:
            self._history[key] = stamps
        else:
            self._history.pop(key, None)
        return stamps

    def _sweep(self, now: float) -> None:
        """Evict every key with no calls left inside its window."""
        cutoff = now - self.window_s
        expired = [
            key
            for key, stamps in self._history.items()
            if not any(t > cutoff for t in stamps)
        ]
        for key in expired:
            del self._history[key]

    def check(self, key: str, now: float) -> bool:
        """Would a call by ``key`` at ``now`` be allowed? Does not spend."""
        self._sweep(now)
        return len(self._prune(key, now)) < self.limit

