class Consumer:
    """Apply (account, seq, delta) messages to per-account balances.

    Messages carry a monotonically increasing sequence number per account.
    A message is applied only when its sequence is exactly the next expected
    one; redeliveries and stale (older) messages are dropped, and messages
    that arrive early (a gap) are held until the gap is filled.
    """

    def __init__(self) -> None:
        self.balances: dict[str, int] = {}
        # Next sequence number expected for each account.
        self._next: dict[str, int] = {}
        # Held messages per account: seq -> delta, waiting for the gap to fill.
        self._pending: dict[str, dict[int, int]] = {}

    def _next_seq(self, account: str) -> int:
        return self._next.get(account, 1)

    def apply(self, account: str, seq: int, delta: int) -> bool:
        """Apply ``delta`` to ``account``'s balance. Returns True if applied."""
        nxt = self._next_seq(account)

        if seq < nxt:
            # Stale redelivery: already applied (or superseded). Drop it.
            return False

        if seq > nxt:
            # A gap: hold the message until the missing sequence arrives.
            self._pending.setdefault(account, {})[seq] = delta
            return False

        # seq == nxt: apply, then flush any now-contiguous held messages.
        self.balances[account] = self.balances.get(account, 0) + delta
        self._next[account] = nxt + 1

        pending = self._pending.get(account)
        if pending:
            while self._next[account] in pending:
                held = pending.pop(self._next[account])
                self.balances[account] += held
                self._next[account] += 1

        return True

    def balance(self, account: str) -> int:
        return self.balances.get(account, 0)

