class LruTtlCache:
    """Hold at most ``cap`` entries, each living at most ``ttl`` seconds.

    An entry expires ``ttl`` seconds after it was last set. Reading an entry
    refreshes its recency, and when the cache is full the live entry whose
    last use is oldest is evicted. Expired entries never occupy capacity:
    they are dropped before a set evicts anything.
    """

    def __init__(self, cap: int, ttl: float) -> None:
        if cap < 1:
            raise ValueError("cap must be at least 1")
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        self.cap = cap
        self.ttl = ttl
        # key -> (value, set_at, last_used)
        self._store: dict[str, list] = {}

    def _expired(self, entry: list, now: float) -> bool:
        return now - entry[1] >= self.ttl

    def _drop_expired(self, now: float) -> None:
        for key in [k for k, e in self._store.items() if self._expired(e, now)]:
            del self._store[key]

    def get(self, key: str, now: float) -> object | None:
        """Return the value for ``key``, or None if absent or expired."""
        entry = self._store.get(key)
        if entry is None:
            return None
        if self._expired(entry, now):
            del self._store[key]
            return None
        entry[2] = now  # refresh recency
        return entry[0]

    def set(self, key: str, value: object, now: float) -> None:
        """Store ``value`` under ``key`` set at ``now``."""
        self._drop_expired(now)
        if key in self._store:
            self._store[key] = [value, now, now]
            return
        if len(self._store) >= self.cap:
            lru = min(self._store, key=lambda k: self._store[k][2])
            del self._store[lru]
        self._store[key] = [value, now, now]

    def __len__(self) -> int:
        return len(self._store)

