class Consumer:
    """Apply (account, seq, delta) messages to per-account balances.

    Messages carry a per-account monotonically increasing sequence number.
    A message is applied only when its sequence is exactly the next expected
    one. Redeliveries (already applied) are no-ops, stale older messages are
    dropped, and gaps are held until the missing sequences arrive.
    """

    def __init__(self) -> None:
        self.balances: dict[str, int] = {}
        self._next_seq: dict[str, int] = {}
        self._held: dict[str, dict[int, int]] = {}

    def apply(self, account: str, seq: int, delta: int) -> bool:
        """Apply ``delta`` to ``account``'s balance. Returns True if applied."""
        next_seq = self._next_seq.get(account, 1)
        if seq < next_seq:
            # Stale redelivery: older than the newest applied sequence.
            return False
        if seq > next_seq:
            # Gap: hold the message until the missing sequences arrive.
            self._held.setdefault(account, {})[seq] = delta
            return False

        # seq == next_seq: apply, then flush any now-contiguous held messages.
        self._apply(account, delta)
        next_seq += 1
        held = self._held.get(account)
        if held:
            while next_seq in held:
                self._apply(account, held.pop(next_seq))
                next_seq += 1
            if not held:
                self._held.pop(account, None)
        self._next_seq[account] = next_seq
        return True

    def _apply(self, account: str, delta: int) -> None:
        self.balances[account] = self.balances.get(account, 0) + delta

    def balance(self, account: str) -> int:
        return self.balances.get(account, 0)

