from __future__ import annotations

from collections import deque


class RateLimitExceeded(Exception):
    """Raised when a key has spent its allowance in the current window."""


class RateLimiter:
    """Cap each key at ``limit`` calls per ``window_s`` seconds.

    The window slides with each key's own history: a call is allowed when
    fewer than ``limit`` calls by the same key landed in ``[now - window_s,
    now)``. The interval is left-open, so a call exactly ``window_s`` seconds
    after an earlier call does not count that earlier call.
    """

    def __init__(self, limit: int, window_s: float) -> None:
        if limit < 1:
            raise ValueError("limit must be at least 1")
        if window_s <= 0:
            raise ValueError("window_s must be positive")
        self.limit = limit
        self.window_s = window_s
        self._calls: dict[str, deque[float]] = {}  # key -> call timestamps

    def _cutoff(self, now: float) -> float:
        # Entries strictly greater than the cutoff are inside [now-W, now).
        return now - self.window_s

    def _prune(self, key: str, now: float) -> deque[float]:
        times = self._calls[key]
        cutoff = self._cutoff(now)
        while times and times[0] <= cutoff:
            times.popleft()
        return times

    def _sweep(self, now: float) -> None:
        """Drop expired keys everywhere so quiet keys do not leak memory."""
        for key in list(self._calls):
            if not self._prune(key, now):
                del self._calls[key]

    def check(self, key: str, now: float) -> bool:
        """Would a call by ``key`` at ``now`` be allowed? Does not spend."""
        times = self._calls.get(key)
        if times is None:
            return True
        cutoff = self._cutoff(now)
        count = sum(1 for t in times if t > cutoff)
        return count < self.limit

    def call(self, key: str, now: float) -> float:
        """Record a call by ``key`` at ``now``; return the retry-after in seconds.

        Raises ``RateLimitExceeded`` when ``limit`` calls already landed in
        the last ``window_s`` seconds.
        """
        self._sweep(now)
        times = self._calls.get(key)
        if times is None:
            times = deque()
            self._calls[key] = times
        else:
            self._prune(key, now)
        if len(times) >= self.limit:
            retry = times[0] + self.window_s - now
            raise RateLimitExceeded(f"{key}: retry in {retry:.3f}s")
        times.append(now)
        return 0.0

    def active_keys(self) -> int:
        """How many keys currently have a call inside the window."""
        return len(self._calls)

"""Rebuilding state from an event log, with snapshots to skip the prefix."""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class Snapshot:
    """A materialized state plus how many log events it already covers."""

    state: int
    covered: int  # number of leading log events folded into `state`


def fold(state: int, event: int) -> int:
    """Apply one event to the state."""
    return state + event


def load_state(log: list[int], snapshot: Snapshot | None = None) -> int:
    """Rebuild the counter from ``log``, seeding from ``snapshot`` when given.

    When a snapshot is supplied its covered count is validated against the log
    and only the events after the covered prefix are folded on top of it.
    """
    if snapshot is None:
        state = 0
        start = 0
    else:
        if not 0 <= snapshot.covered <= len(log):
            raise ValueError(
                f"snapshot covers {snapshot.covered} events, "
                f"but the log holds {len(log)}"
            )
        state = snapshot.state
        start = snapshot.covered

    for event in log[start:]:
        state = fold(state, event)
    return state

