    The newest applied sequence is tracked per account. A message is applied
    only when its sequence is exactly the next one; redeliveries and stale
    messages are dropped, and out-of-order messages are held until the gap
    before them is filled.
    """

    def __init__(self) -> None:
        self.balances: dict[str, int] = {}
        self.applied: dict[str, int] = {}
        self.held: dict[str, dict[int, int]] = {}

    def apply(self, account: str, seq: int, delta: int) -> bool:
        """Apply ``delta`` to ``account``'s balance. Returns True if applied."""
        last = self.applied.get(account, 0)
        if seq <= last:
            # Redelivery or stale message: never apply it.
            return False
        if seq > last + 1:
            # Gap: hold the message until the missing sequences arrive.
            self.held.setdefault(account, {})[seq] = delta
            return False

        # seq == last + 1: apply it and flush any now-contiguous held messages.
        self.balances[account] = self.balances.get(account, 0) + delta
        self.applied[account] = seq

        pending = self.held.get(account)
        if pending:
            nxt = seq + 1
            while nxt in pending:
                self.balances[account] += pending.pop(nxt)
                self.applied[account] = nxt
                nxt += 1
            if not pending:
                del self.held[account]
        return True

    def balance(self, account: str) -> int:
        return self.balances.get(account, 0)

