from collections import OrderedDict


class LruTtlCache:
    """Hold at most ``cap`` entries, each living at most ``ttl`` seconds.

    Entries expire ``ttl`` seconds after they were last set.  A ``get`` on a
    live entry refreshes its recency; when the cache is full the live entry
    whose last use is oldest is evicted.  Expired entries never occupy
    capacity: they are dropped before any eviction decision is made.
    """

    def __init__(self, cap: int, ttl: float) -> None:
        if cap < 1:
            raise ValueError("cap must be at least 1")
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        self.cap = cap
        self.ttl = ttl
        # key -> (value, set_at); OrderedDict order is recency (LRU first).
        self._store: "OrderedDict[str, tuple[object, float]]" = OrderedDict()

    def _expired(self, set_at: float, now: float) -> bool:
        return now - set_at >= self.ttl

    def _drop_expired(self, now: float) -> None:
        stale = [k for k, (_, set_at) in self._store.items() if self._expired(set_at, now)]
        for key in stale:
            del self._store[key]

    def get(self, key: str, now: float) -> object | None:
        """Return the value for ``key``, or None if absent or expired."""
        entry = self._store.get(key)
        if entry is None:
            return None
        value, set_at = entry
        if self._expired(set_at, now):
            del self._store[key]
            return None
        self._store.move_to_end(key)
        return value

    def set(self, key: str, value: object, now: float) -> None:
        """Store ``value`` under ``key`` set at ``now``."""
        self._drop_expired(now)
        if key in self._store:
            self._store[key] = (value, now)
            self._store.move_to_end(key)
            return
        if len(self._store) >= self.cap:
            self._store.popitem(last=False)  # evict least-recently-used
        self._store[key] = (value, now)

    def __len__(self) -> int:
        return len(self._store)

"""Holding a slot for a TTL, then confirming it."""

from __future__ import annotations


class SlotTaken(Exception):
    """Raised when a slot is already held or booked."""


class HoldExpired(Exception):
    """Raised when a confirm arrives after the hold's deadline."""


class Reservations:
    """Reserve a slot for ``ttl`` seconds, then confirm or lose it.

    A hold is recorded with the time it was taken and expires exactly at
    ``reserved_at + ttl``. The deadline is inclusive: confirming at that
    instant still succeeds, while anything later raises ``HoldExpired``.
    An expired hold frees the slot for a new reserve. A confirmed booking
    is permanent.
    """

    def __init__(self, ttl: float) -> None:
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        self.ttl = ttl
        self._holds: dict[str, float] = {}      # slot -> reserved_at
        self._confirmed: set[str] = set()

    def _live_hold(self, slot: str, now: float) -> bool:
        """Is there a hold on ``slot`` that is still live at ``now``?"""
        reserved_at = self._holds.get(slot)
        if reserved_at is None:
            return False
        return now <= reserved_at + self.ttl

    def reserve(self, slot: str, now: float) -> float:
        """Hold ``slot`` at ``now``; return the expiry time."""
        if slot in self._confirmed:
            raise SlotTaken(slot)
        if self._live_hold(slot, now):
            raise SlotTaken(slot)
        # Any stale hold is dead; drop it and take the slot afresh.
        self._holds.pop(slot, None)
        self._holds[slot] = now
        return now + self.ttl

    def confirm(self, slot: str, now: float) -> None:
        """Finalize a held slot. Raises HoldExpired after the deadline."""
        if slot in self._confirmed:
            return
        if not self._live_hold(slot, now):
            # Drop the dead hold (if any) so the slot is free again.
            self._holds.pop(slot, None)
            raise HoldExpired(f"{slot}: no live hold")
        del self._holds[slot]
        self._confirmed.add(slot)

    def is_free(self, slot: str, now: float) -> bool:
        """Is ``slot`` available to reserve at ``now``?"""
        return slot not in self._confirmed and not self._live_hold(slot, now)

"""Applying sequenced account-update messages exactly once."""

from __future__ import annotations


class Consumer:
    """Apply (account, seq, delta) messages to per-account balances.

    Messages carry a monotonically increasing sequence number per account.
    A message is applied only when its sequence is exactly the next expected
    one; redeliveries and out-of-order older messages are no-ops, and a
    message with a gap is held until the missing sequence arrives.
    """

    def __init__(self) -> None:
        self.balances: dict[str, int] = {}
        self._next_seq: dict[str, int] = {}
        self._held: dict[str, dict[int, int]] = {}

    def apply(self, account: str, seq: int, delta: int) -> bool:
        """Apply ``delta`` to ``account``'s balance. Returns True if applied."""
        next_seq = self._next_seq.get(account, 1)

        if seq < next_seq:
            # Duplicate redelivery or stale out-of-order message: drop it.
            return False

        if seq > next_seq:
            # Gap: hold the message until the missing sequence arrives.
            self._held.setdefault(account, {})[seq] = delta
            return False

        # seq == next_seq: apply, then flush any now-contiguous held messages.
        self._apply(account, delta)
        next_seq += 1
        held = self._held.get(account)
        while held is not None and next_seq in held:
            self._apply(account, held.pop(next_seq))
            next_seq += 1
        self._next_seq[account] = next_seq
        return True

    def _apply(self, account: str, delta: int) -> None:
        self.balances[account] = self.balances.get(account, 0) + delta

    def balance(self, account: str) -> int:
        return self.balances.get(account, 0)

